<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { ShieldCheck, KeyRound, RefreshCw, Check } from 'lucide-vue-next';
import { api, command } from '../api';
const busy=ref(false),error=ref(''),employeeRef=ref(''),generated=ref(''),invites=ref<any[]>([]),items=ref<any[]>([]),uploads=ref<any[]>([]),audits=ref<any[]>([]),reconciliation=ref<any|null>(null),operations=ref<any|null>(null);
const uploadId=ref(''),reason=ref(''),fishId=ref(''),nickname=ref(''),nicknameReason=ref(''),recheckReason=ref('人工复核账目与数据库状态均正常');
const emit=defineEmits<{toast:[string]}>();
function rows(v:any){return Array.isArray(v)?v:v?.items??[];}
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){await run(async()=>{const [a,b,c,d,e,f]=await Promise.all([api('/admin/invites'),api('/admin/shop/items'),api('/admin/reconciliation'),api('/admin/operations'),api('/admin/uploads'),api('/admin/audit')]);invites.value=rows(a);items.value=rows(b);reconciliation.value=c;operations.value=d;uploads.value=rows(e);audits.value=rows(f);});}
async function invite(){await run(async()=>{const r=await command<any>('/admin/invites',{employeeRef:employeeRef.value});generated.value=r.inviteCode;employeeRef.value='';emit('toast','邀请码已创建，明文仅本次显示');});}
async function update(item:any){await run(async()=>{await command(`/admin/shop/items/${item.id}`,{price:item.price,enabled:item.enabled,version:item.version},'PATCH');emit('toast','商品已更新');});await load();}
async function recheck(){await run(async()=>{await command('/admin/operations/recheck',{reason:recheckReason.value});emit('toast','完整对账通过，资产写入状态已重新核对');});await load();}
async function moderateUpload(id:string,status:'ACTIVE'|'REMOVED'){await run(async()=>{await command(`/admin/uploads/${id}`,{status,reason:reason.value},'PATCH');emit('toast',status==='REMOVED'?'图片已下架，相关角色恢复默认皮肤':'图片已恢复使用');reason.value='';uploadId.value='';});await load();}
async function moderateNickname(){await run(async()=>{await command(`/admin/fish/${fishId.value}`,{nickname:nickname.value,reason:nicknameReason.value},'PATCH');emit('toast','昵称已更新并写入审计');fishId.value='';nickname.value='';nicknameReason.value='';});}
onMounted(load);
</script>
<template>
  <div class="eyebrow"><ShieldCheck :size="17"/>管理员工具</div><h1>让珊瑚海好好运行</h1><p class="panel-intro">管理操作由服务器鉴权并保留审计，邀请码明文只显示一次。</p>
  <div v-if="error" class="inline-error" role="alert">{{error}}</div><button class="text-button" @click="load" :disabled="busy"><RefreshCw :size="13"/>刷新管理数据</button>
  <label class="form-field">员工唯一标识<input v-model="employeeRef" maxlength="100" placeholder="例如公司员工编号" aria-label="员工唯一标识"/></label><button class="primary wide" @click="invite" :disabled="busy||!employeeRef.trim()"><KeyRound :size="17"/>生成单次邀请码</button>
  <div v-if="generated" class="purchase-confirm"><b>仅本次显示，请妥善保存</b><p class="invite-code">{{generated}}</p><button class="text-button" @click="generated=''">我已保存，隐藏明文</button></div>
  <details class="bind-section"><summary>已发放邀请码</summary><div v-for="i in invites" :key="i.id" class="ledger-row">{{i.employeeRef??i.employee_ref}} · {{i.usedBy??i.used_by?'已使用':'未使用'}} · 到期 {{new Date(i.expiresAt??i.expires_at).toLocaleString('zh-CN')}}</div></details>
  <details class="bind-section"><summary>商品上下架与价格</summary><div v-for="item in items" :key="item.id" class="admin-product"><b>{{item.name}}</b><input type="number" v-model.number="item.price" min="0" :aria-label="`${item.name}价格`"/><label><input type="checkbox" v-model="item.enabled"/>上架</label><button @click="update(item)" :disabled="busy">保存</button></div></details>
  <details class="bind-section"><summary>图片处置 · 最近 {{uploads.length}} 项</summary><label class="form-field">处置原因<input v-model="reason" maxlength="200" aria-label="图片处置原因"/></label><div v-for="asset in uploads" :key="asset.id" class="admin-record"><span><b>{{asset.id}}</b><small>{{asset.user_id}} · {{asset.width}}×{{asset.height}} · {{asset.status}}</small></span><button v-if="asset.status==='ACTIVE'" class="danger-button" :disabled="busy||!reason.trim()" @click="moderateUpload(asset.id,'REMOVED')">下架</button><button v-else :disabled="busy||!reason.trim()" @click="moderateUpload(asset.id,'ACTIVE')">恢复</button></div><label class="form-field">指定图片编号<input v-model="uploadId" aria-label="指定图片编号"/></label><button class="danger-button" :disabled="busy||!uploadId||!reason.trim()" @click="moderateUpload(uploadId,'REMOVED')">按编号下架</button></details>
  <details class="bind-section"><summary>违规昵称处置</summary><label class="form-field">角色编号<input v-model="fishId" aria-label="角色编号"/></label><label class="form-field">新昵称<input v-model="nickname" maxlength="12" aria-label="处置后的昵称"/></label><label class="form-field">处置原因<input v-model="nicknameReason" maxlength="200" aria-label="昵称处置原因"/></label><button class="primary wide" :disabled="busy||!fishId||nickname.trim().length<2||nicknameReason.trim().length<2" @click="moderateNickname">更新昵称并记录审计</button></details>
  <details class="bind-section"><summary>最近审计记录 · {{audits.length}}</summary><div v-for="entry in audits" :key="entry.id" class="admin-record audit-record"><span><b>{{entry.action}}</b><small>{{entry.target_type}} / {{entry.target_id}} · {{new Date(entry.created_at).toLocaleString('zh-CN')}}</small><small v-if="entry.reason">原因：{{entry.reason}}</small></span></div><p v-if="!audits.length" class="tiny-label">尚无审计记录。</p></details>
  <h3 class="section-title">账目核对</h3><div v-if="reconciliation" class="reconciliation"><p><Check :size="15"/>{{reconciliation.ok===true?'对账一致':reconciliation.ok===false?'发现异常，资产写入保持暂停':'服务端核对结果'}}</p><pre>{{JSON.stringify(reconciliation,null,2)}}</pre></div><div v-if="operations" class="reconciliation"><p>资产写入：{{operations.assetWrites?.allowed?'开放':'暂停'}}</p><p>连接 {{operations.runtime?.connections??0}} · Tick P95 {{operations.runtime?.tickP95Ms??0}}ms · 待结算 {{operations.runtime?.database?.pending_settlements??0}} · Outbox {{operations.runtime?.database?.outbox_pending??0}}</p><pre v-if="operations.assetWrites?.reasons?.length">{{JSON.stringify(operations.assetWrites.reasons,null,2)}}</pre></div><label class="form-field">重新开放原因<input v-model="recheckReason" maxlength="200" aria-label="重新开放资产写入原因"/></label><button class="primary wide" :disabled="busy||!recheckReason.trim()" @click="recheck">完整复核并重新开放资产写入</button><p class="tiny-label">发现异常不得静默改余额。只有完整对账通过后才能重新开放；操作会进入审计日志。</p>
</template>
<style scoped>
.invite-code{font-family:monospace;overflow-wrap:anywhere;font-size:15px;letter-spacing:1px}.admin-product{display:flex;align-items:center;gap:9px;margin:15px 0;font-size:10px}.admin-product b{flex:1}.admin-product input[type=number]{width:60px;padding:7px;border:1px solid #cfdcce;border-radius:6px;background:#fffff8}.admin-product button,.admin-record button{padding:7px 12px;border-radius:6px;background:#dfebdc;color:#47716b;font-size:10px}.admin-record{display:flex;align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid #dce6dd;font-size:9px}.admin-record>span{min-width:0;flex:1}.admin-record b,.admin-record small{display:block;overflow-wrap:anywhere}.admin-record small{margin-top:3px;color:#78918d}.audit-record{align-items:flex-start}.reconciliation{background:#edf1e7;border-radius:12px;padding:15px;color:#688a80;font-size:11px}.reconciliation>p{display:flex;align-items:center;gap:7px}.reconciliation pre{font-size:9px;max-height:240px;overflow:auto;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}
</style>
